 document.addEventListener('ksmarjaa:credential',()=>{if(credentialBlocked){catalogLoaded=false;if(busy){stop=true;paused=false;}options.activity({level:'warning',category:'generate',title:'Pending API key',message:'Pengiriman ditahan karena API key dihapus atau penghapusannya tertunda. Generation ID tetap disimpan.',notify:false});void persist().catch(()=>{});}update();});
 const $=<T extends HTMLElement=HTMLElement>(s:string)=>root.querySelector<T>(s)!;
 let resetDialogResolve:((accepted:boolean)=>void)|null=null;const resetDialog=$<HTMLDialogElement>('#reset-confirm-dialog');resetDialog.addEventListener('close',()=>{resetDialogResolve?.(resetDialog.returnValue==='confirm');resetDialogResolve=null;});$('#reset-dialog-cancel').onclick=()=>resetDialog.close('cancel');$('#reset-dialog-confirm').onclick=()=>resetDialog.close('confirm');resetDialog.addEventListener('click',event=>{if(event.target===resetDialog)resetDialog.close('cancel');});function confirmBatchReset(kind:'failed'|'completed',batch:number,count:number,name:string){return new Promise<boolean>(resolve=>{resetDialogResolve=resolve;$('#reset-dialog-batch').textContent=`BATCH ${String(batch).padStart(2,'0')} · ${count} PRODUK`;$('#reset-dialog-title').textContent=kind==='completed'?'Generate ulang batch ini?':'Siapkan ulang produk gagal?';$('#reset-dialog-message').textContent=kind==='completed'?`${count} produk pada batch ${batch} sudah selesai. Anda akan membuat generation baru untuk batch ini.`:`${count} produk gagal atau dibatalkan pada batch ${batch} akan disiapkan untuk dicoba kembali.`;$('#reset-dialog-note').textContent=kind==='completed'?'File hasil yang sudah tersimpan tetap aman. Request baru dapat memakai saldo provider.':'Hanya produk gagal/dibatalkan pada batch ini yang direset. Status sukses dan ambigu tetap aman.';$<HTMLButtonElement>('#reset-dialog-confirm').innerHTML=`${icon('rotate-ccw')} ${kind==='completed'?'Reset & generate ulang':'Reset produk gagal'}`;options.icons();resetDialog.showModal();});}
 function persist(){const snapshot={schema:1,jobs,runIds,outputRoots,selected,selectedStore,updatedAt:new Date().toISOString()};localStorage.setItem(JOBS,JSON.stringify(jobs));localStorage.setItem('ksmarjaa:generate-runs:v1',JSON.stringify(runIds));localStorage.setItem('ksmarjaa:generate-output-roots:v1',JSON.stringify(outputRoots));if(!desktop)return Promise.resolve();persistChain=persistChain.catch(()=>{}).then(()=>invoke<void>('generation_state_save',{state:snapshot}));return persistChain;}
 function hydrateState(){if(hydration)return hydration;hydration=(async()=>{if(!desktop){stateLoaded=true;update();return;}try{const saved=await invoke<{jobs?:Job[];runIds?:Record<string,string>;outputRoots?:Record<string,string>;selected?:string;selectedStore?:string}>('generation_state_load',{});if(Array.isArray(saved.jobs)){const merged=new Map(saved.jobs.map(j=>[j.id,j]));for(const localJob of jobs){const disk=merged.get(localJob.id);merged.set(localJob.id,disk?.generationId&&!localJob.generationId?disk:localJob);}jobs=[...merged.values()];}if(saved.runIds&&typeof saved.runIds==='object')runIds={...runIds,...saved.runIds};if(saved.outputRoots&&typeof saved.outputRoots==='object')outputRoots={...outputRoots,...saved.outputRoots};if(saved.selected&&records.some(r=>r.id===saved.selected))selected=saved.selected;if(saved.selectedStore)selectedStore=saved.selectedStore;localStorage.setItem(JOBS,JSON.stringify(jobs));localStorage.setItem('ksmarjaa:generate-runs:v1',JSON.stringify(runIds));localStorage.setItem('ksmarjaa:generate-output-roots:v1',JSON.stringify(outputRoots));if(selected)localStorage.setItem(ACTIVE,selected);stateLoaded=true;stateError='';backfillJobActivity();await persist();}catch(e){stateLoaded=false;stateError=(e as Error).message;options.notify(`Data pemulihan tidak berhasil dibaca. Generate dikunci untuk menjaga status antrean: ${stateError}`,true);}update();})();return hydration;}
 function batchContext(products:Product[],activeJobs:Job[]){const size=Math.max(1,settings?.batchSize||10),total=Math.max(1,Math.ceil(products.length/size));const current=activeJobs.find(j=>['preparing','sending','queued','processing','downloading'].includes(j.status));const pendingIndex=products.findIndex(p=>!activeJobs.some(j=>j.productId===p.id&&j.status==='completed'));const activeIndex=current?products.findIndex(p=>p.id===current.productId):-1;const index=activeIndex>=0?activeIndex:pendingIndex>=0?pendingIndex:Math.max(0,products.length-1);const batch=Math.min(total,Math.floor(index/size)+1);const start=(batch-1)*size;const end=Math.min(products.length,start+size);return{size,total,batch,start,end,index,current,items:products.slice(start,end)};}
 function queueBatchView(products:Product[],ctx:ReturnType<typeof batchContext>){const batch=Math.max(1,Math.min(ctx.total,viewedBatch||ctx.batch));const start=(batch-1)*ctx.size;const end=Math.min(products.length,start+ctx.size);return{batch,start,end,items:products.slice(start,end),followsActive:batch===ctx.batch};}
 function drawJobs(){const target=$('#job-list');const r=record();const products=r?.data.products||[];const activeJobs=jobs.filter(j=>j.manifestId===selected&&j.runId===runId());const ctx=batchContext(products,activeJobs);const view=queueBatchView(products,ctx);if(!products.length){target.innerHTML=`<div class="queue-empty">${icon('layers-3')}<strong>Antrean belum tersedia</strong><span>Pilih manifest untuk memuat produk siap.</span></div>`;options.icons();return;}target.innerHTML=view.items.map((p,n)=>{const index=view.start+n;const job=activeJobs.find(j=>j.productId===p.id);const status=job?.status||'waiting';const labels:Record<string,string>={completed:'Selesai',processing:'Diproses',queued:'Menunggu proses',preparing:'Menyiapkan',sending:'Mengirim',downloading:'Menyimpan',failed:'Gagal',ambiguous:'Perlu cek',cancelled:'Dibatalkan',waiting:'Menunggu'};const detail=job?.error||job?.stage||`${p.identity.motorcycle||p.identity.brand||'Produk'} · ${p.identity.part||p.folder||r!.data.sourceName}`;return`<article class="job-row ${status}" role="listitem" style="--row-index:${n}"><span class="job-number">${String(index+1).padStart(3,'0')}</span><div class="job-description"><strong title="${esc(p.title)}">${esc(p.title)}</strong><small title="${esc(detail)}">${esc(detail)}</small>${status==='processing'||status==='downloading'?`<span class="job-progress"><i style="width:${status==='downloading'?100:Math.max(0,Math.min(100,job?.progress||0))}%"></i></span>`:''}${status==='ambiguous'&&!job?.generationId?`<button class="resolve-job" data-product="${esc(p.id)}" data-mode="ambiguous">Saya sudah cek website · coba lagi</button>`:status==='failed'||status==='cancelled'?`<button class="resolve-job" data-product="${esc(p.id)}" data-mode="${status}">Tinjau &amp; ulangi produk</button>`:''}</div><span class="job-status ${status}">${status==='completed'?icon('circle-check'):status==='processing'||status==='sending'||status==='preparing'||status==='downloading'?icon('loader-circle'):status==='waiting'||status==='queued'?icon('clock-3'):icon('circle-x')}<b>${labels[status]||status}</b></span></article>`;}).join('');target.querySelectorAll<HTMLButtonElement>('.resolve-job').forEach(button=>button.onclick=async()=>{const job=activeJobs.find(j=>j.productId===button.dataset.product&&j.status===button.dataset.mode);if(!job)return;const ambiguous=job.status==='ambiguous';const prompt=ambiguous?'Pastikan generation ini tidak tercatat di website. Jika ternyata sudah diterima, mengulang dapat membuat generation berbayar ganda. Tandai aman dan siapkan request ulang?':'Produk gagal atau dibatalkan. Mengulang akan membuat generation baru dan mungkin mengonsumsi saldo. Siapkan request ulang?';if(!window.confirm(prompt))return;if(job.generationId)(job.generationHistory||=[]).push(job.generationId);job.generationId=undefined;job.status='ready';job.error=undefined;job.progress=undefined;job.stage=undefined;job.finishedAt=undefined;await persist();update();});options.icons();}
