 async function invoke<T>(name:string,args:Record<string,unknown>):Promise<T>{if(['generation_submit','generation_status','generation_download','generation_templates','generation_catalog'].includes(name)){if(credentialBlocked)throw new Error('Pending API key · request belum dikirim.');const snapshot=await loadSettings();if(!snapshot.hasApiKey){setCredentialAvailability(false);throw new Error('Pending API key · API key lokal tidak tersedia; request belum dikirim.');}}if(!desktop)throw new Error('Proses Generate memerlukan aplikasi Windows agar API key tetap tersimpan aman dan request tidak terkena batasan CORS preview.');const {invoke}=await import('@tauri-apps/api/core');return invoke<T>(name,args);}
