  async function loadTemplates(storeId:string){
    templates=[];selectedTemplate='';templatesError='';if(!storeId){update();return;}templatesLoading=true;update();let failureLogged=false;
    try{
      await pace(false);
      const reply=await invoke<{status:number;requestId?:string;contentType?:string;body:{data:Template[];message?:string}}>('generation_templates',{storeId:Number(storeId),timeoutSeconds:settings!.requestTimeoutSeconds});
      if(reply.status!==200){const detail=responseDetail(reply.body);const message='HTTP '+reply.status+' · '+detail+(reply.requestId?' · Request ID '+reply.requestId:'');options.activity({level:'error',category:'generate',title:'Template ditolak · HTTP '+reply.status,message,notify:false});failureLogged=true;throw new Error('Template gagal dimuat: '+message);}
      templates=reply.body.data||[];options.activity({level:'success',category:'generate',title:'Template toko dimuat · HTTP 200',message:templates.length+' template tersedia. Request ID '+(reply.requestId||'tidak dikirim oleh server')+'.',notify:false});selectedTemplate=templates[0]?String(templates[0].id):'';if(!selectedTemplate)templatesError='Toko ini belum memiliki template aktif.';await persist();
    }catch(e){const detail=(e as Error).message||String(e);templatesError=detail.length>220?detail.slice(0,217)+'…':detail;if(!failureLogged)options.activity({level:'error',category:'generate',title:'Koneksi template gagal',message:detail,notify:false});throw e;
    }finally{templatesLoading=false;update();}
  }
