   const select=$<HTMLSelectElement>('#gen-store');select.disabled=false;select.innerHTML='<option value="">Pilih toko</option>'+stores.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');if(stores.some(s=>String(s.id)===selectedStore)){select.value=selectedStore;try{await loadTemplates(selectedStore);}catch{/* Catalog remains usable; the template error and server detail are shown inline and in Activity Log. */}}else{selectedStore='';selectedTemplate='';templates=[];}
